-- Noir & Co. catalogue content seed. Uses existing schema and existing image assets only.
SET @brand=(SELECT id FROM brands WHERE slug='noir-co.' LIMIT 1);
SET @cat_t_shirts=(SELECT id FROM categories WHERE slug='t-shirts' LIMIT 1);
SET @cat_shirts=(SELECT id FROM categories WHERE slug='shirts' LIMIT 1);
SET @cat_hoodies=(SELECT id FROM categories WHERE slug='hoodies' LIMIT 1);
SET @cat_sweatshirts=(SELECT id FROM categories WHERE slug='sweatshirts' LIMIT 1);
SET @cat_jackets=(SELECT id FROM categories WHERE slug='jackets' LIMIT 1);
SET @cat_coats=(SELECT id FROM categories WHERE slug='coats' LIMIT 1);
SET @cat_jeans=(SELECT id FROM categories WHERE slug='jeans' LIMIT 1);
SET @cat_trousers=(SELECT id FROM categories WHERE slug='trousers' LIMIT 1);
SET @cat_shorts=(SELECT id FROM categories WHERE slug='shorts' LIMIT 1);
SET @cat_sneakers=(SELECT id FROM categories WHERE slug='sneakers' LIMIT 1);
SET @cat_bags=(SELECT id FROM categories WHERE slug='bags' LIMIT 1);
SET @cat_accessories=(SELECT id FROM categories WHERE slug='accessories' LIMIT 1);
ON DUPLICATE KEY UPDATE description=VALUES(description),image=VALUES(image);
UPDATE products SET status='published' WHERE slug LIKE 'noir-%';
SELECT p.id,c.id FROM products p JOIN collections c
WHERE p.slug LIKE 'noir-%' AND (c.slug IN ('essentials','new-arrivals') OR (c.slug='premium-collection' AND p.price>=150000) OR (c.slug='streetwear' AND p.category_id IN (@cat_hoodies,@cat_sweatshirts,@cat_jackets)) OR (c.slug='summer-collection' AND p.category_id IN (@cat_shirts,@cat_shorts)) OR (c.slug='winter-collection' AND p.category_id IN (@cat_coats,@cat_jackets,@cat_hoodies)) OR (c.slug='best-sellers' AND MOD(p.id,6)=0) OR (c.slug='limited-edition' AND MOD(p.id,11)=0));
SELECT p.id,CASE WHEN x.n IN (1,4,6) THEN '/uploads/products/098a7d0e542fe1ff393a121a.png' ELSE '/uploads/products/de0b224c304be0f556090189.png' END,CONCAT(p.slug,'-',x.n,'.png'),IF(x.n=1,1,0),x.n
FROM products p JOIN (SELECT 1 n UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7) x
WHERE p.slug LIKE 'noir-%' AND NOT EXISTS (SELECT 1 FROM product_images e WHERE e.product_id=p.id);
SELECT p.id,CONCAT(p.name,' / ',a.n),CONCAT(p.sku,'-',a.n),p.price,p.quantity,JSON_OBJECT('color',CASE WHEN MOD(p.id,3)=0 THEN 'Obsidian' WHEN MOD(p.id,3)=1 THEN 'Stone' ELSE 'Ecru' END,'size',a.n,'fit',COALESCE(p.tags,'relaxed fit'))
FROM products p JOIN (SELECT 'S' n UNION ALL SELECT 'M' UNION ALL SELECT 'L' UNION ALL SELECT 'XL') a
WHERE p.slug LIKE 'noir-%' AND NOT EXISTS (SELECT 1 FROM product_variants v WHERE v.product_id=p.id);
